52	  const springValue = useSpring(motionValue, { damping: 40, stiffness: 100 });
53	  const [display, setDisplay] = useState("0");
54	
55	  useEffect(() => {
56	    if (isInView) motionValue.set(value);
57	  }, [isInView, motionValue, value]);
58	
59	  useEffect(() => {
60	    const unsubscribe = springValue.on("change", (v) => {
61	      setDisplay(Math.round(v).toLocaleString());
62	    });
63	    return unsubscribe;
64	  }, [springValue]);
65	
66	  return <span ref={ref}>{display}{suffix}</span>;
67	}
