9	  showLabel?: boolean;
10	  className?: string;
11	}
12	
13	export const ScoreRing = React.forwardRef<HTMLDivElement, ScoreRingProps>(function ScoreRing({
14	  score,
15	  size = 120,
16	  strokeWidth = 8,
17	  showLabel = true,
18	  className,
19	}, ref) {
20	  const [animatedOffset, setAnimatedOffset] = useState(0);
